export async function GET() {
  try {
    const supabase = createAdminSupabase();
    const results = [];

    for (const tool of SEED_TOOLS) {
      // Check if tool already exists by name
      const { data: existing } = await supabase
        .from('tools')
        .select('id, name')
        .eq('name', tool.name)
        .single();

      if (existing) {
        // Update existing tool
        const { error: updateError } = await supabase
          .from('tools')
          .update({
            slug: tool.slug,
            website_url: tool.website_url,
            affiliate_url: tool.affiliate_url,
            desc_en: tool.desc_en,
            desc_simple_en: tool.desc_simple_en,
            task_category: tool.task_category,
            best_for: tool.best_for,
            tags: tool.tags,
            badge: tool.badge,
            manual_rank: tool.manual_rank,
            rank_in_task: tool.rank_in_task,
            why_pick: tool.why_pick,
            is_active: true,
          })
          .eq('id', existing.id);

        if (updateError) {
          results.push({ name: tool.name, status: 'error', error: updateError.message });
        } else {
          results.push({ name: tool.name, status: 'updated' });
        }
      } else {
        // Insert new tool
        const { error: insertError } = await supabase
          .from('tools')
          .insert({ ...tool, is_active: true });

        if (insertError) {
          results.push({ name: tool.name, status: 'error', error: insertError.message });
        } else {
          results.push({ name: tool.name, status: 'inserted' });
        }
      }
    }

    return NextResponse.json({
      message: 'Tool seed completed',
      results,
    });
  } catch (error) {
    console.error('Tool seed error:', error);
    return NextResponse.json(
      { error: 'Failed to seed tools' },
      { status: 500 }
    );
  }
}

